# -*- coding: utf-8 -*-
"""R71 blind predictions seat S4: batches B10 B11 B12 (60 cases, all liuyao).
Writes predictions/<case_id>.json per case. No reads of any judging/gold files.
Trigger convention (per frozen prompt, no codified definition in method):
 changed_main = a moving line's transformation (化出用神/忌化用/回头生克 flipping
   or creating the main line) materially changed the initial main judgment;
 reserve_used = main yongshen taken from hidden (伏神) line;
 disputed = yongshen selection contested (two-present unresolved / card-vs-chart
   mismatch / multi-hexagram composite). reason states the case fact.
"""
import json, os

OUT = "/home/hatch/workspace/divination/benchmark/phase3/runs/round71/predictions"
os.makedirs(OUT, exist_ok=True)

DATA = []
def add(cid, pred, basis, conf, cm, ru, disp, reason):
    DATA.append({
        "case_id": cid, "prediction_text": pred, "basis": basis,
        "confidence": conf,
        "trigger": {"changed_main": cm, "reserve_used": ru,
                    "disputed": disp, "reason": reason}})

